solution.solution.rs:
fn is_leap_year(year: i32) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

fn clock(minutes: i32) -> String {
    let m = minutes.rem_euclid(24 * 60);
    format!("{}:{:02}", m / 60, m % 60)
}

fn digit_sum(n: i64) -> u32 {
    digits_of(n.unsigned_abs())
}

fn digits_of(n: u64) -> u32 {
    if n < 10 { n as u32 } else { (n % 10) as u32 + digits_of(n / 10) }
}

fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 { a } else { gcd(b, a % b) }
}

fn sign_word(x: f64) -> &'static str {
    if x < 0.0 {
        "negative"
    } else if x == 0.0 {
        "zero"
    } else {
        "positive"
    }
}

unitTests:
test("leap years", || {
    check_eq(is_leap_year(2024), true);
    check_eq(is_leap_year(2023), false);
    check_eq(is_leap_year(1900), false);
    check_eq(is_leap_year(2000), true);
});

test("clock times", || {
    check_eq(clock(125), "2:05");
    check_eq(clock(0), "0:00");
    check_eq(clock(1440), "0:00");
    check_eq(clock(-30), "23:30");
    check_eq(clock(3000), "2:00");
});

test("digit sums", || {
    check_eq(digit_sum(90210), 12);
    check_eq(digit_sum(-555), 15);
    check_eq(digit_sum(0), 0);
    check_eq(digit_sum(i64::MIN), 89);
});

test("gcd", || {
    check_eq(gcd(84, 36), 12);
    check_eq(gcd(17, 5), 1);
    check_eq(gcd(0, 9), 9);
    check_eq(gcd(0, 0), 0);
});

test("sign words", || {
    check_eq(sign_word(-2.5), "negative");
    check_eq(sign_word(0.0), "zero");
    check_eq(sign_word(1e-9), "positive");
});

